<script lang="ts">
 import {onMount,onDestroy} from 'svelte';export let companyId:string;export let conversationId:string;export let attachmentId:string;export let accessSignal:AbortSignal;
 let root:HTMLElement,observer:IntersectionObserver|null=null,controller=new AbortController(),url='',name='Attached image',visible=true,error='',loading=true,alive=true;
 function clear(){controller.abort();if(url)URL.revokeObjectURL(url);url='';visible=false;}
 onMount(()=>{const token=localStorage.token||'',company=companyId,room=conversationId,reference=attachmentId,base='/api/v1/companies/'+encodeURIComponent(company)+'/drive/channel-attachments/'+encodeURIComponent(reference),query='?room='+encodeURIComponent(room);const fresh=()=>alive&&!accessSignal.aborted&&!controller.signal.aborted&&company===companyId&&room===conversationId&&token===(localStorage.token||'');
 async function load(){observer?.disconnect();if(!fresh())return;try{const response=await fetch(base+query,{signal:controller.signal,credentials:'same-origin',cache:'no-store',headers:{Authorization:'Bearer '+token,Accept:'application/json'}});if(!response.ok)throw Error('Image access is unavailable.');const envelope=await response.json(),meta=envelope.data;if(!fresh())return;if(envelope.contract!=='starli.company-drive.v2'||meta?.id!==reference||meta.companyId!==company||meta.roomId!==room)throw Error('Image attachment scope could not be verified.');if(!['image/png','image/jpeg','image/webp'].includes(meta.mime)){visible=false;return;}if(!Number.isSafeInteger(meta.size)||meta.size>8388608)throw Error('Image is too large to preview.');name=meta.filename||'Attached image';const content=await fetch(base+'/content'+query,{signal:controller.signal,credentials:'same-origin',cache:'no-store',headers:{Authorization:'Bearer '+token,Accept:meta.mime}});if(!content.ok||content.headers.get('content-type')?.split(';')[0]!==meta.mime)throw Error('Image content could not be verified.');const blob=await content.blob();if(blob.size>8388608)throw Error('Image is too large to preview.');if(fresh())url=URL.createObjectURL(blob);}catch(cause){if(fresh())error=(cause as Error).message;}finally{if(fresh())loading=false;}}
 accessSignal.addEventListener('abort',clear,{once:true});if(typeof IntersectionObserver!=='undefined'){observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting))void load();},{rootMargin:'200px'});observer.observe(root);}else void load();return()=>accessSignal.removeEventListener('abort',clear);});onDestroy(()=>{alive=false;observer?.disconnect();clear();});
</script>
<figure class="chat-image" bind:this={root}>{#if visible}{#if loading}<p role="status">Loading attached image…</p>{:else if error}<p role="alert">{error}</p>{:else if url}<img src={url} alt={name}/><figcaption><span>{name}</span><a href={url} download={name}>Download image</a></figcaption>{/if}{/if}</figure>
<style>.chat-image{margin:12px 0;max-width:100%;white-space:normal}.chat-image:empty{display:none}.chat-image img{display:block;max-width:100%;max-height:460px;border-radius:10px;object-fit:contain;border:1px solid #e2e8f0;background:#f8faff}.chat-image figcaption{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:11px;padding:9px 0;color:#64748b}.chat-image a{color:#2563eb}.chat-image p{padding:16px;border:1px solid #e2e8f0;border-radius:9px;font-size:11px;color:#64748b}</style>
